import{z as A,x as B,o as t,c as i,q as l,j as E,D as r,d as o,s as n,S as d,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"TSO 与弱序","description":"","frontmatter":{"title":"TSO 与弱序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tso-weak.md","filePath":"cs/tso-weak.md","lastUpdated":1791063341000}'),p={name:"cs/tso-weak.md"};function S(C,e,m,T,c,f){const s=B("Mermaid");return t(),i("div",null,[e[2]||(e[2]=l('<h1 id="tso-与弱序" tabindex="-1">TSO 与弱序 <a class="header-anchor" href="#tso-与弱序" aria-label="Permalink to &quot;TSO 与弱序&quot;">​</a></h1><div class="epigraph"><p>允许后到的 load 越过尚未耗尽的 store，store 缓冲才能对单线程藏延迟；他核可能先看见后面的写。</p><footer>—— 据 SPARC Architecture Manual (TSO)；Sewell, Sarkar, Owens, Nardelli and Myreen, x86-TSO, CACM 2010；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/memory-consistency">上一课</a>钉了 Lamport 顺序一致性，并点名 TSO 允许 load 提前、用 fence 收回。<a href="/cs/store-buffer">存储缓冲与 load 绕过</a>已经给出硬件对象。本课不重讲 MESI。缺口是把放宽写成可编程的合同：总存储序（TSO）允许什么、弱序还放掉什么，以及栅栏插在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SC 要求每核的 load/store 序出现在全局交错里。有 store 缓冲时，本核 load 已经绕过年长 store（对不同地址），他核若先看到后面那条已提交的 store、尚未看到前面那条仍在缓冲里的 store，SC 失败。TSO 承认这一条放宽：<strong>同一核上 store 之间、load 之间保持程序序，允许 load 越过更早的 store</strong>；所有核的 store 仍有一个总序。</p><p>弱序（许多 ARM/RISC-V 配置接近）还允许 store-store、load-load 重排，只在同步指令处恢复。缺口不是新的 cache 状态，而是程序员必须把发布/获取写成栅栏或带序的 load/store。</p><p><span class="marginnote">x86 对普通 mov 接近 TSO（另有 store 原子性等细则）。RISC-V 默认弱，<code>fence</code> 与带 aq/rl 的 AMO 收回序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TSO 下 Dekker 算法失败：双方写自己的旗再读对方的旗，可能都读到旧值。修复：在写旗与读对方之间加 store-load 栅栏（x86 的 <code>mfence</code> 一类），抽干缓冲。弱序下互斥还要管 load-load 与 store-store，用更全的 fence 或 acquire/release。</p>',9)),(t(),E(d,null,{default:r(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22store%20%E5%85%A5%E7%BC%93%E5%86%B2%22%5D%20--%3E%20TSO%5B%22TSO%EF%BC%9A%E5%90%8E%20load%20%E5%8F%AF%E8%B6%8A%E8%BF%87%22%5D%0A%20%20TSO%20--%3E%20FENCE%5B%22fence%EF%BC%9A%E7%BC%93%E5%86%B2%E6%8E%92%E7%A9%BA%E6%89%8D%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20WEAK%5B%22%E5%BC%B1%E5%BA%8F%EF%BC%9Aload%2Fstore%20%E5%9D%87%E5%8F%AF%E9%87%8D%E6%8E%92%22%5D%20--%3E%20REL%5B%22release%2Facquire%20%E6%94%B6%E4%B8%80%E5%AF%B9%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"单线程 ISA 仍靠同地址转发保持。放宽只暴露给并发观察者。",-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},[o("术语翻译：store-load 栅栏 = 「在下一条 load 之前，先把缓冲里攒着的写全部排出去」。x86 的普通 mov 已各自保持程序序，唯独家底那一处放宽是 load 越过年长 store；"),a("code",null,"mfence"),o(" 一类指令把这一处也堵上，Dekker 才恢复正确。")])],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"性能：TSO 几乎免费（缓冲本来就要）；SC 要实现要么侦听缓冲对全局可见性，要么延迟 load，IPC 掉。弱序把更多重叠交给硬件，把正确性交给同步库。阿姆达尔：只在锁与发布点付栅栏，不在每条 store 付。",-1)),e[7]||(e[7]=a("p",null,"与窥探/目录无关：传播手段给出单行的「当前值」；TSO/弱序给出多行之间允许的交错集合。两者都要。",-1)),e[8]||(e[8]=a("p",null,"三种模型各自的代价与责任落在哪：",-1)),(t(),E(d,null,{default:r(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22TSO%3A%20store%20%E7%BC%93%E5%86%B2%E7%85%A7%E5%B8%B8%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20C1%5B%22%E5%87%A0%E4%B9%8E%E9%9B%B6%E9%A2%9D%E5%A4%96%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20M2%5B%22SC%3A%20load%20%E9%9C%80%E7%AD%89%E5%85%A8%E5%B1%80%E5%8F%AF%E8%A7%81%22%5D%20--%3E%20C2%5B%22load%20%E8%A2%AB%E5%BB%B6%E8%BF%9F%2C%20IPC%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20M3%5B%22%E5%BC%B1%E5%BA%8F%3A%20%E6%9B%B4%E5%A4%9A%E9%87%8D%E6%8E%92%E7%95%99%E7%BB%99%E7%A1%AC%E4%BB%B6%22%5D%20--%3E%20C3%5B%22%E6%AD%A3%E7%A1%AE%E6%80%A7%E7%A7%BB%E4%BA%A4%E5%90%8C%E6%AD%A5%E5%BA%93%22%5D%0A%20%20C1%20--%3E%20T%5B%22%E5%8F%AA%E5%9C%A8%E9%94%81%E4%B8%8E%E5%8F%91%E5%B8%83%E7%82%B9%E4%BB%98%20fence%22%5D%0A%20%20C2%20--%3E%20T%0A%20%20C3%20--%3E%20T%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=l('<p><span class="marginnote">直觉类比：MESI 是快递系统，保证「任一时刻每件包裹只有一份正本、改动全局可见」；TSO 与弱序是邮规，规定「信件可以不按寄出顺序送达」。前者管单行缓存的新旧，后者管多行之间的先后——两个不同的问题，缺一不可。</span></p><p><span class="marginnote">常见误区：弱序不等于「随机乱序」。同地址的程序序与 store→load 同地址转发始终保持，放掉的只是<strong>不同地址</strong>之间的顺序，并且只在并发观察者面前暴露——单线程自己永远看不出任何差别。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 C++ <code>memory_order</code> 枚举写完，不引入线性一致性。也不把 RISC-V RVWMO 的每一条公理抄进来。互连与 NUMA 让「总序里的下一步」物理上更远，栅栏更贵——下一课。GPU 的宽松模型不在本栏。</p><p>后课默认：谈到 x86 风格共享内存，先按 TSO 想 store 缓冲；谈到 RISC-V/ARM，先当弱序，同步用 fence。访存延迟随节点变，是 NUMA 课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TSO：允许 load 越过年长 store，store 有全局总序；Dekker 要 fence。</li><li>弱序更松，同步点用 acquire/release 或全栅栏收回 SC 片段。</li><li>远程内存与互连延迟是下一课。</li><li>出处：SPARC TSO；Sewell et al., <em>CACM</em>, 2010；Lamport, <em>IEEE TC</em>, 1979；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const O=A(p,[["render",S]]);export{D as __pageData,O as default};
